// Copyright (c) 2026, the Flutter Agent Harness authors.
// Use of this source code is governed by a MIT license that can be found
// in the LICENSE file.

// Part of agent_service.dart: the agent-event handling member of
// [AgentService] lives here so the main file stays under the 2800-line
// guard. Same library, so private members resolve; notifications go
// through `_notify()` (`notifyListeners` is @protected, callable only
// inside the class).
//
// The full agent-event switch: streaming deltas, transcript tiles
// (assistant/thinking/tool/system/widget), the dynamic-message marker
// splice, Live Activity status, idle watchdog rearming, end-of-run
// persistence + auto-compaction + queued-run continuation.

part of 'agent_service.dart';

/// Internal marker in `_pendingRequestRecords`: the flush turns it into
/// a real `ModelChangeRecord` (issue #440) — the System row the request
/// summary that follows on the chain stamps with the blob pointers (F7a).
/// Never passed to `appendCustomEntry`.
const String _pendingModelChangeMarker = '_pending_model_change';

extension AgentServiceEvents on AgentService {
  Future<void> _onAgentEvent(AgentEvent event, CancelToken cancelToken) async {
    // Any event proves the run is alive — rearm the idle watchdog.
    if (event is! AgentEndEvent) _armIdleWatchdog();
    _trajectory.applyEvent(event);
    // Event-kind dispatch (issue #486): one handler per kind; the sealed
    // AgentEvent family keeps the cases exact, unknown kinds stay no-ops.
    switch (event) {
      case AgentStartEvent():
        _onAgentStart();
      case TurnStartEvent():
        _onTurnStart();
      case MessageUpdateEvent(:final assistantMessageEvent):
        _onMessageUpdate(assistantMessageEvent);
      case MessageEndEvent(:final message):
        _onMessageEnd(message);
      case ToolExecutionStartEvent(:final toolName, :final args):
        _onToolExecutionStart(toolName, args);
      case ToolExecutionEndEvent(
        :final toolName,
        :final result,
        :final isError,
      ):
        _onToolExecutionEnd(
          toolName: toolName,
          result: result,
          isError: isError,
        );
      case ModelRequestEvent():
        _persistModelRequest(event);
      case AgentEndEvent():
        await _onAgentEnd();
      default:
        break;
    }
  }

  /// Run start: fresh streaming state, steering ledger and a fresh
  /// dynamic-message budget (the cap is per agent turn, host-enforced).
  void _onAgentStart() {
    isStreaming = true;
    _currentAssistantMessage = null;
    _turnStartCount = 0;
    pendingSteerTexts.clear();
    dynamicMessages.onRunStart();
    _notify();
  }

  /// Continuation turns (steering injected mid-run) start with a second
  /// TurnStartEvent; clear the pending banner now so it doesn't outlive
  /// the injected user messages.
  void _onTurnStart() {
    if (_turnStartCount > 0 && pendingSteerTexts.isNotEmpty) {
      pendingSteerTexts.clear();
      _notify();
    }
    _turnStartCount++;
  }

  void _onMessageUpdate(AssistantMessageEvent assistantMessageEvent) {
    if (assistantMessageEvent is TextDeltaEvent) {
      _appendAssistantDelta(assistantMessageEvent.delta);
    } else if (assistantMessageEvent is ThinkingDeltaEvent) {
      _appendThinkingDelta(assistantMessageEvent.delta);
    }
  }

  void _onMessageEnd(Message message) {
    if (message is UserMessage) {
      // User messages (initial prompts and injected steering) reach the
      // transcript through the agent loop so ordering matches the context.
      messages.add(_toChatMessage(message));
      // If this text was shown as pending while the agent was busy, drop
      // it from the banner now that it is in the live transcript.
      final text = _userMessageText(message);
      if (text != null) pendingSteerTexts.remove(text);
      _notify();
    } else if (message is AssistantMessage) {
      _finalizeAssistant(message);
    }
    _persistSoon();
  }

  /// Tool calls can run long (builds, installs) without producing agent
  /// events — the idle watchdog must not fire during them.
  void _onToolExecutionStart(String toolName, Map<String, dynamic> args) {
    _activeToolCalls++;
    messages.add(
      FahChatMessage(
        role: 'system',
        content: '[$toolName] ${_shortArgs(args)}',
      ),
    );
    _pushLiveActivityStatus();
    _notify();
  }

  void _onToolExecutionEnd({
    required String toolName,
    required ToolExecutionResult result,
    required bool isError,
  }) {
    _activeToolCalls--;
    _armIdleWatchdog();
    if (AgentService._kMutatingToolNames.contains(toolName)) {
      // "Hook" for file-watching UI: the agent may have changed files.
      fsRevision.value++;
    }
    _persistSoon();
    final text = result.content
        .whereType<TextContent>()
        .map((b) => b.text)
        .join('\n');
    messages.add(
      FahChatMessage(
        role: 'tool',
        content: text,
        toolName: toolName,
        isError: isError,
      ),
    );
    // A dynamic message presented by this tool call renders directly
    // under its result tile (presentation order = call order).
    if (toolName == 'dynamic_message') {
      final presented = dynamicMessages.takePendingMarker();
      if (presented != null) {
        messages.add(
          FahChatMessage(
            role: DynamicMessagesService.markerRole,
            content: presented.title,
            data: presented.id,
          ),
        );
        // The ✦ sheet's jump-to-message targets `msg-<index>` rows.
        presented.markerIndex = messages.length - 1;
      }
    }
    _pushLiveActivityStatus();
    _notify();
  }

  /// Run end: stop streaming, cancel the idle watchdog, persist the
  /// transcript (best effort), auto-compact + resume an over-window
  /// interrupted turn, then start a queued run if any.
  Future<void> _onAgentEnd() async {
    _idleWatchdog?.cancel();
    isStreaming = false;
    _currentAssistantMessage = null;
    _notify();
    // Session persistence is best effort: a failed append must not
    // propagate back into the agent's event plumbing (a throwing
    // listener re-enters the loop's failure path, duplicates the
    // failure events, and escapes the run as an unhandled error).
    //
    // `_persist()` is single-flight: the finalizer either runs the pass
    // itself or joins the in-flight drain (which re-runs any state that
    // landed mid-sweep). It resolves only when every persist-worthy
    // change so far is on disk, so when this returns the transcript is
    // fully written and the idle boundary (`waitForIdle`) can't overtake
    // a pending append (issue #1102).
    try {
      await _persist();
    } on Object {
      // The transcript stays in memory; the next run retries the
      // missed appends (see _persistedCount).
    }
    final compacted = await _maybeAutoCompact();
    // The loop's over-window guard stopped the run: once the
    // post-run compaction freed the window, continue the interrupted
    // turn on its own (once per user text) instead of idling with an
    // error — a live session that hit the guard mid-task (200676/200k
    // on glm) used to sit dead until a manual "continue".
    final lastMessage = _agent.state.messages.lastOrNull;
    if (!_overWindowAutoResumed &&
        compacted &&
        lastMessage is AssistantMessage &&
        isContextWindowExhaustedError(lastMessage.errorMessage)) {
      _overWindowAutoResumed = true;
      Future(
        () => _runWithTimeout(
          () => _agent.prompt(AgentService._overWindowContinuationNotice),
        ),
      );
    }
    // Steering/follow-up messages queued during the run get their own
    // run once this lifecycle fully finished — also after a manual
    // stop, so a queued message never silently dies in the transcript.
    if (_agent.hasQueuedMessages()) {
      Future(() => _runWithTimeout(() => _agent.continueRun()));
    }
  }

  /// Extracts the textual content of a [UserMessage] for matching against
  /// [pendingSteerTexts]. Returns `null` for empty or non-text messages.
  String? _userMessageText(UserMessage message) {
    …

content.text:
      if (text.isNotEmpty) TextContent(text: text),
      ImageContent(data: base64Encode(bytes), mimeType: mimeType),
    ];
    final message = UserMessage(content: content, timestamp: DateTime.now());
    if (_agent.state.isStreaming) {
      _agent.steer(message);
      pendingSteerTexts.add(text.isEmpty ? '[image]' : text);
      notifyListeners();
      return;
    }
    _runWithTimeout(() => _agent.promptMessage(message));
  }

  /// Idle watchdog: the run aborts only when NOTHING comes back for
  /// [_responseTimeout] — any event (tokens, tool calls) proves the model is
  /// alive and rearms it. Replaces the previous whole-run timeout, which
  /// killed long coding tasks ("Request was aborted" after 90 s of healthy
  /// streaming). Long tool calls suppress it via [_activeToolCalls].
  Timer? _idleWatchdog;
  int _activeToolCalls = 0;

  /// Aborts the current run, if any.
  @override
  void abort() => _agent.abort();

  /// The in-flight `_persist` drain, or `null` when idle. While one pass
  /// sweeps the transcript, late triggers mark `_persistDirty` and await
  /// this drain instead of dropping their payload (issue #1102) — and a
  /// stored future from another zone can't stall a stored-null guard, so
  /// no cross-zone future capture is possible here.
  Future<void>? _persistPass;

  /// Set when a `_persist` trigger landed while a pass was in flight; the
  /// running drain re-runs the full-state sweep once more before it ends.
  bool _persistDirty = false;

  @override
  void dispose() {
    if (identical(maybeCurrent, this)) maybeCurrent = null;
    _disposed = true;
    // Drop the sleep-prevention assertion (issue #325): best-effort and
    // fire-and-forget — dispose stays synchronous.
    unawaited(powerAssertion?.release());
    // Disposing the service cancels an in-flight run: the agent's idle
    // watchdog would otherwise outlive the host by minutes (and wedge
    // widget tests' fake_async invariants on a pending timer).
    _agent.abort();
    _agentNetwork?.dispose();
    _compactExpand?.dispose();
    if (_subagentManager != null) _scheduledMessages.dispose();
    _inboxWatchTimer?.cancel();
    unawaited(_taskCompletionsSub?.cancel());
    _idleWatchdog?.cancel();
    _liveActivityEndTimer?.cancel();
    _sessionWatchTimer?.cancel();
    fsRevision.dispose();
    externalSessionRevision.dispose();
    _trajectory.dispose();
    dynamicMessages.dispose();
    super.dispose();
  }

  /// Switches the backend (provider/model/key) for subsequent messages while
  /// keeping the visible transcript and the current session.
  ///
  /// Any in-flight run is aborted first and awaited, so no zombie stream
  /// survives the switch; the deliberate abort's error banner is cleared.
  /// The [Agent] itself is reused — only its model, system prompt, and
  /// stream function are swapped — so tool wiring and the transcript live
  /// on. For WebLLM the settings form has already run `loadModel` (the
  /// engine is a singleton), so the new stream function reuses the warm
  /// instance. The switch is recorded as a `model_change` session record.
  Future<void> reconfigure(AgentConfig config) async {
    // Issue #327: refuse a connection whose model and auth resolve from
    // DIFFERENT registry rows, or a hosted/CodeMie endpoint with no
    // credential on this surface — before any state changes (fail fast,
    // no side effects; pickers surface the message verbatim).
    final problem = providerConnectionProblem(
      _providerRegistry,
      config,
      extensionHost: isExtensionHost(),
    );
    if (problem != null) {
      debugPrint('[Fa] reconfigure refused: $problem');
      throw ProviderConnectionException(problem);
    }
    abort();
    await waitForIdle();
    final newModel = config.toModel();
    debugPrint(
      '[Fa] reconfigure: baseUrl=${config.baseUrl}, '
      'apiKey.len=${config.apiKey.length}, '
      'isCodeMie=${isCodeMieProvider(config.baseUrl)}, '
      'model.headers=${newModel.headers?.keys.toList()}, '
      'streamApiKey.len=${isCodeMieProvider(config.baseUrl) ? 0 : config.apiKey.length}',
    );
    _agent.state.model = newModel;
    _agent.state.systemPrompt = _composeSystemPrompt(config);
    _agent.streamFunction = _streamFunctionFor(config);
    _providerKind = config.providerKind;
    _activeBaseUrl = config.baseUrl;
    _activeApiKey = config.apiKey;
    _responseTimeout = _isOnDeviceKind(config.providerKind)
        ? const Duration(minutes: 10)
        : isCodeMieProvider(config.baseUrl)
        ? const Duration(minutes: 5)
        : const Duration(seconds: 90);
    error = null;
    notifyListeners();
    // Best effort: a failed marker write must not break the switch.
    try {
      await _session?.appendModelChange(
        provider: config.providerKind,
        modelId: config.modelId,
      );
    } on Object {
      // Session persistence is best effort here.
    }
  }

  /// Lists persisted sessions, newest first (across all provider dirs
  /// under [sessionsRoot]). Cheap: reads only the JSONL headers.
  Future<List<SessionMetadata>> listSessions() async {
    try {
      final roots = _includeSharedSessionRoots
          ? allSessionRoots(sessionsRoot)
          : <String>[sessionsRoot];
      if (roots.length <= 1) {
        return await _repo.list();
      }
      return await mergeSessionsAcrossRoots(
        roots: roots,
        listRoot: (root) async => root == sessionsRoot
            ? _repo.list()
            : JsonlSessionRepo(fs: env, sessionsRoot: root).list(),
