  Future<void> _flushDynamicWidgets(Session session) async {
    for (final data in dynamicMessages.drainRecordPayloads()) {
      await session.appendCustomEntry(
        customType: DynamicMessagesService.recordType,
        data: data,
      );
    }
  }

