    test('sendText appends user and assistant messages', () async {
      final env = MemoryExecutionEnv();
      final service = AgentService(
        agent: _createAgent(_singleTextResponse('hello back')),
        env: env,
        sessionsRoot: '/sessions',
      );
      await service.initialize();

      await service.sendText('hello');
      await service.waitForIdle();

      expect(service.messages.length, 2);
      expect(service.messages[0].role, 'user');
      expect(service.messages[0].content, 'hello');
      expect(service.messages[1].role, 'assistant');
      expect(service.messages[1].content, 'hello back');
    });

    test(
      'the model request summary persists before its assistant message',
      () async {
        final env = MemoryExecutionEnv();
        final service = AgentService(
          agent: _createAgent(_singleTextResponse('hello back')),
          env: env,
          sessionsRoot: '/sessions',
        );
        await service.initialize();

        await service.sendText('hello');
        await service.waitForIdle();

        // The loop emits ModelRequestEvent before the provider call; the
        // service persists it as a context-omitted CustomRecord whose data
        // round-trips the request summary.
        final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
        final metadata = (await repo.list()).single;
        final session = await repo.open(metadata);
        final entries = await session.getEntries();
        final summaries = entries
            .whereType<CustomRecord>()
            .where((r) => r.customType == 'model_request_summary')
            .toList();
        expect(summaries, hasLength(1));
        // Issue #385 F1: the unseen prompt version lands as its own
        // content-addressed blob record beside the summary.
        final blobs = entries
            .whereType<CustomRecord>()
            .where((r) => r.customType == 'trajectory_prompt_blob')
            .toList();
        expect(blobs, hasLength(1));

        // Ordering: the summary sits on the chain before the assistant
        // message record it produced (the replay walk expects that).
        final summaryIndex = entries.indexOf(summaries.single);
        final assistantIndex = entries.indexWhere(
          (e) => e is MessageRecord && e.message is AssistantMessage,
        );
        expect(summaryIndex, lessThan(assistantIndex));

        // Replaying the persisted branch rebuilds the Request tab data.
        final builder = TrajectorySnapshotBuilder();
        for (final record in entries) {
          builder.append(record);
        }
        final assistant = builder
            .build()
            .records
            .whereType<TrajectoryAssistantRecord>()
            .single;
        expect(assistant.requestDetail, isNotNull);
        expect(assistant.requestDetail!.systemPromptChars, greaterThan(0));
      },
    );

    test(
      'a persist pass skipped by the run finalizer still lands by idle (#1102)',
      () async {
        final env = _DeferredAppendEnv();
        final service = AgentService(
          agent: _createAgent(_yieldBeforeText('hello back')),
          env: env,
          sessionsRoot: '/sessions',
        );
        await service.initialize();

        await service.sendText('hello');
        await service.waitForIdle();

        // Appends resolve on a later event-loop turn, so at the idle
        // boundary any still-pending pass is provably unfinished. The
        // finalizer's persist must join the queue (not early-return),
        // or idle resolves while the assistant append is still pending.
        final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
        final session = await repo.open((await repo.list()).single);
        final entries = await session.getEntries();
        expect(
          entries.whereType<MessageRecord>().any(
            (r) => r.message is AssistantMessage,
          ),
          isTrue,
          reason:
              'assistant record missing at the idle boundary: '
              '${entries.map((e) => e.runtimeType).toList()}',
        );
      },
    );

    test(
      'coalesced persist passes land the full final state by idle (#1102)',
      () async {
        final env = _DeferredAppendEnv();
        final service = AgentService(
          agent: _createAgent(_yieldBeforeText('hello back')),
          env: env,
          sessionsRoot: '/sessions',
        );
        await service.initialize();

        await service.sendText('hello');
        await service.waitForIdle();

        // Every pass re-runs the snapshot diff, so the final on-disk state
        // matches the in-memory transcript — user, summary, prompt blob and
        // assistant record, in replay order.
        final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
        final session = await repo.open((await repo.list()).single);
        final entries = await session.getEntries();
        final summaryIndex = entries.indexWhere(
          (e) => e is CustomRecord && e.customType == 'model_request_summary',
        );
        final assistantIndex = entries.indexWhere(
          (e) => e is MessageRecord && e.message is AssistantMessage,
        );
        expect(
          entries.whereType<MessageRecord>().map((r) => r.message.role),
          ['user', 'assistant'],
          reason: 'transcript rows missing at idle: ${entries.map((e) => e.runtimeType).toList()}',
        );
        expect(summaryIndex, lessThan(assistantIndex));
      },
    );

