        if (attachment.path != null && attachment.bytes == null) {
          buffer.writeln('[attached file: ${attachment.path}]');
        }
      }
      if (m.content.isNotEmpty) buffer.writeln(m.content);
      buffer.writeln();
    }
    return buffer.toString();
  }

