    _inboxWatchTimer?.cancel();
    unawaited(_taskCompletionsSub?.cancel());
    _idleWatchdog?.cancel();
    _liveActivityEndTimer?.cancel();
    _sessionWatchTimer?.cancel();
    fsRevision.dispose();
    externalSessionRevision.dispose();
    _trajectory.dispose();
    dynamicMessages.dispose();
